				logger.Fatal("failed to init OAuth login handler", zap.Error(err))
			}
			logger.Info("OAuth login routes registered",
				zap.Bool("google", cfg.GoogleClientID != ""),
				zap.Bool("github", cfg.LoginGitHubClientID != ""),
