default: // "fts"
	results, err = s.searchWikiFTS(ctx, userID, req)
	if err == nil && len(results) == 0 {
		// Fall back to ILIKE if FTS returns nothing (handles partial words)
		results, err = s.searchWikiBlocks(ctx, userID, req)
	}
}

