// float32SliceToVectorString converts a float32 slice to pgvector string format: "[0.1,0.2,0.3]"
func float32SliceToVectorString(v []float32) string {
	var b strings.Builder
	b.WriteByte('[')
	for i, f := range v {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(fmt.Sprintf("%g", f))
	}
	b.WriteByte(']')
	return b.String()
}

