          <svg class="w-5 h-5" fill="currentColor" viewBox="0 0 24 24"><path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg>
        </a>
        <a id="top-share-linkedin" href="#" target="_blank" rel="noopener noreferrer" aria-label="Share on LinkedIn" class="share-icon-btn">
          <svg class="w-5 h-5" fill="currentColor" viewBox="0 0 24 24"><path d="M20.447 20.452h-3.554v-5.569c0-1.328-.027-3.037-1.852-3.037-1.853 0-2.136 1.445-2.136 2.939v5.667H9.351V9h3.414v1.561h.046c.477-.9 1.637-1.85 3.37-1.85 3.601 0 4.267 2.37 4.267 5.455v6.286zM5.337 7.433a2.062 2.062 0 01-2.063-2.065 2.064 2.064 0 112.063 2.065zm1.782 13.019H3.555V9h3.564v11.452zM22.225 0H1.771C.792 0 0 .774 0 1.729v20.542C0 23.227.792 24 1.771 24h20.451C23.2 24 24 23.227 24 22.271V1.729C24 .774 23.2 0 22.222 0h.003z"/></svg>
        </a>
        <button id="top-share-copy" aria-label="Copy link" class="share-icon-btn">
          {{icon "link" "w-5 h-5"}}
        </button>
      </div>
    </div>

    <!-- Article Content -->
    <div class="prose prose-lg dark:prose-invert max-w-none mb-8" id="article-content">
        {{if .Post.ContentHTML}}
            {{.Post.ContentHTML}}
        {{else}}
            {{.Post.Content}}
        {{end}}
    </div>

    <!-- Social Share -->
    <div class="share-section">
        <div class="share-buttons" id="share-buttons">
            <button id="share-native" aria-label="Share" class="share-btn" style="display:none">
                {{icon "share" "w-4 h-4"}}
                Share
            </button>
            <a id="share-x" href="#" target="_blank" rel="noopener noreferrer" class="share-btn" aria-label="Share on X">
                <svg class="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg>
                X
            </a>
            <a id="share-linkedin" href="#" target="_blank" rel="noopener noreferrer" class="share-btn" aria-label="Share on LinkedIn">
                <svg class="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M20.447 20.452h-3.554v-5.569c0-1.328-.027-3.037-1.852-3.037-1.853 0-2.136 1.445-2.136 2.939v5.667H9.351V9h3.414v1.561h.046c.477-.9 1.637-1.85 3.37-1.85 3.601 0 4.267 2.37 4.267 5.455v6.286zM5.337 7.433a2.062 2.062 0 01-2.063-2.065 2.064 2.064 0 112.063 2.065zm1.782 13.019H3.555V9h3.564v11.452zM22.225 0H1.771C.792 0 0 .774 0 1.729v20.542C0 23.227.792 24 1.771 24h20.451C23.2 24 24 23.227 24 22.271V1.729C24 .774 23.2 0 22.222 0h.003z"/></svg>
                LinkedIn
            </a>
            <button id="share-copy" class="share-btn">
                {{icon "clipboard-copy" "w-4 h-4"}}
                Copy Link
            </button>
        </div>
    </div>

    <!-- About the Author(s) -->
    <section style="margin-top:3rem;padding-top:2.5rem;border-top:1px solid var(--border-light, #e5e7eb)">
      <!-- Primary author -->
      <div class="flex items-start mb-6" style="gap:20px">
        <a href="/users/{{.Post.Username}}" class="flex-shrink-0">
          {{if .Post.AuthorAvatarURL}}
          <img src="{{thumbURL .Post.AuthorAvatarURL}}" alt="{{.Post.AuthorDisplayName}}" width="56" height="56" class="rounded-full object-cover" style="width:56px;height:56px">
          {{else}}
          <span class="flex items-center justify-center rounded-full text-white font-bold text-lg" style="width:56px;height:56px;background:linear-gradient(135deg,var(--accent,#0d9488),#6366f1)">{{initial .Post.AuthorDisplayName}}</span>
          {{end}}
        </a>
        <div class="min-w-0">
          <div class="text-xs font-semibold uppercase tracking-wider mb-1" style="color:var(--accent)">Written by</div>
          <a href="/users/{{.Post.Username}}" class="text-lg font-bold hover:underline" style="color:var(--text-primary)">{{.Post.AuthorDisplayName}}</a>
          {{if .Post.AuthorBio}}
          <p class="mt-1 text-sm leading-relaxed" style="color:var(--text-secondary)">{{.Post.AuthorBio}}</p>
          {{end}}
        </div>
      </div>
      <!-- Contributors -->
      {{if .Contributors}}
      {{range .Contributors}}
      <div class="flex gap-4 items-start mb-4 pl-4 ml-4 border-l-2" style="border-color:var(--border-light)">
        <a href="/users/{{.Username}}" class="flex-shrink-0">
          {{if .AvatarURL}}
          <img src="{{thumbURL .AvatarURL}}" alt="{{.DisplayName}}" width="40" height="40" class="rounded-full object-cover" style="width:40px;height:40px">
          {{else}}
          <span class="flex items-center justify-center rounded-full text-white font-bold text-sm" style="width:40px;height:40px;background:linear-gradient(135deg,var(--accent,#0d9488),#6366f1)">{{initial .DisplayName}}</span>
          {{end}}
        </a>
        <div class="min-w-0">
          <div class="text-xs font-medium" style="color:var(--text-tertiary)">Contributor</div>
          <a href="/users/{{.Username}}" class="text-sm font-semibold hover:underline" style="color:var(--text-primary)">{{.DisplayName}}</a>
          {{if .Bio}}
          <p class="mt-0.5 text-xs leading-relaxed" style="color:var(--text-secondary)">{{.Bio}}</p>
          {{end}}
        </div>
      </div>
      {{end}}
      {{end}}
    </section>

    <!-- Comments Section -->
    <section class="mt-12 pt-8 border-t border-gray-200 dark:border-gray-700" id="comments-section">
      <h2 class="text-2xl font-bold mb-6">Comments</h2>

      <div id="comments-list" class="mb-8">
        <p class="text-gray-500 dark:text-gray-400 text-sm" id="comments-loading">Loading comments...</p>
      </div>

      {{if .LoggedIn}}
        {{if .UserPermissions.CanComment}}
        <div class="comment-compose-box" id="comment-compose">
          <div id="reply-banner" class="reply-banner" style="display:none;">
            <span id="reply-banner-text"></span>
            <button type="button" id="cancel-reply" class="cancel-reply-btn">✕ Cancel</button>
          </div>
          <div class="comment-toolbar">
            <button type="button" class="fmt-btn" data-cmd="bold" title="Bold"><b>B</b></button>
            <button type="button" class="fmt-btn fmt-italic" data-cmd="italic" title="Italic"><i>I</i></button>
            <button type="button" class="fmt-btn" data-cmd="code" title="Inline code">`</button>
            <button type="button" class="fmt-btn" data-cmd="codeblock" title="Code block">{ }</button>
            <button type="button" class="fmt-btn" data-cmd="link" title="Link">🔗</button>
            <span class="toolbar-sep"></span>
            <span class="toolbar-hint">Markdown supported</span>
          </div>
          <textarea id="new-comment-content" rows="4" maxlength="5000"
            class="comment-textarea"
            placeholder="Write a comment… Markdown supported"></textarea>
          <div class="comment-compose-footer">
            <span id="comment-char-count" class="comment-char-count">0 / 5000</span>
            <button id="submit-comment" class="btn btn-primary">Post Comment</button>
          </div>
        </div>
        {{end}}
      {{else}}
      <div class="signin-prompt">
        <p class="signin-prompt-text">Sign in to join the discussion</p>
        <a href="/auth/github?return_to=/blog/{{.Post.Slug}}" class="gh-signin-link">
          <svg width="16" height="16" fill="currentColor" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12 2C6.477 2 2 6.484 2 12.017c0 4.425 2.865 8.18 6.839 9.504.5.092.682-.217.682-.483 0-.237-.008-.868-.013-1.703-2.782.605-3.369-1.343-3.369-1.343-.454-1.158-1.11-1.466-1.11-1.466-.908-.62.069-.608.069-.608 1.003.07 1.531 1.032 1.531 1.032.892 1.53 2.341 1.088 2.91.832.092-.647.35-1.088.636-1.338-2.22-.253-4.555-1.113-4.555-4.951 0-1.093.39-1.988 1.029-2.688-.103-.253-.446-1.272.098-2.65 0 0 .84-.27 2.75 1.026A9.564 9.564 0 0112 6.844c.85.004 1.705.115 2.504.337 1.909-1.296 2.747-1.027 2.747-1.027.546 1.379.202 2.398.1 2.651.64.7 1.028 1.595 1.028 2.688 0 3.848-2.339 4.695-4.566 4.943.359.309.678.92.678 1.855 0 1.338-.012 2.419-.012 2.747 0 .268.18.58.688.482A10.019 10.019 0 0022 12.017C22 6.484 17.522 2 12 2z" clip-rule="evenodd"/></svg>
          Sign in with GitHub to comment
        </a>
      </div>
      {{end}}
    </section>

    <!-- Annotations Section -->
    <div id="annotation-bar" class="mt-6 flex items-center gap-3">
      <button id="toggle-annotations" class="btn btn-secondary text-sm flex items-center gap-2">
        {{icon "chat" "w-4 h-4"}}
        <span id="toggle-annotations-label">Show Annotations</span>
      </button>
      <span id="annotation-count" class="text-xs text-gray-500"></span>
    </div>

    <div id="annotation-panel" style="display:none;" class="mt-4 rounded-xl border border-gray-200 dark:border-gray-700 p-5">
      <h3 class="font-semibold mb-4">Annotations</h3>
      <div id="annotation-list" class="space-y-4">
        <p class="text-sm text-gray-500">No annotations yet.</p>
      </div>
      {{if not .LoggedIn}}
      <div class="mt-4 pt-4 border-t border-gray-200 dark:border-gray-700 text-sm text-gray-500">
        <a href="/auth/github?return_to=/blog/{{.Post.Slug}}" class="hover:underline" style="color: var(--accent);">Sign in with GitHub</a> to annotate this post.
      </div>
      {{end}}
    </div>

    <!-- Navigation (only shown when prev/next posts exist) -->
    {{if or .PrevPost .NextPost}}
    <nav class="post-nav">
        <div class="post-nav-inner">
            {{if .PrevPost}}
            <a href="/blog/{{.PrevPost.Slug}}" class="post-nav-link post-nav-prev">
                {{icon "chevron-left" "post-nav-arrow"}}
                <div>
                    <div class="post-nav-label">Previous</div>
                    <div class="post-nav-title">{{if gt (len .PrevPost.Title) 50}}{{slice .PrevPost.Title 0 50}}...{{else}}{{.PrevPost.Title}}{{end}}</div>
                </div>
            </a>
            {{else}}<div></div>{{end}}
            {{if .NextPost}}
            <a href="/blog/{{.NextPost.Slug}}" class="post-nav-link post-nav-next">
                <div>
                    <div class="post-nav-label">Next</div>
                    <div class="post-nav-title">{{if gt (len .NextPost.Title) 50}}{{slice .NextPost.Title 0 50}}...{{else}}{{.NextPost.Title}}{{end}}</div>
                </div>
                {{icon "chevron-right" "post-nav-arrow"}}
            </a>
            {{else}}<div></div>{{end}}
        </div>
    </nav>
    {{end}}
</article>

<!-- Back to Top -->
<button 
    id="back-to-top"
    class="back-to-top"
    aria-label="Back to top"
>
    {{icon "arrow-up" "w-5 h-5"}}
</button>

