<!-- Native Lightbox Dialog -->
<dialog id="lightbox-dialog" class="lightbox-dialog">
    <img id="lightbox-img" src="" alt="">
    <button id="lightbox-close" class="lightbox-close" aria-label="Close">&times;</button>
